+import { join, resolve } from "@std/path";
+import { ConfigParseError } from "./errors.ts";
+import type { ConfigOptions } from "./types.ts";
+
+export interface LoadedConfig {
+  path?: string;
+  values: Record<string, unknown>;
+}
+
+/** Load a command configuration. This intentionally runs during `parse()`. */
+export async function loadConfig(options: ConfigOptions): Promise<LoadedConfig> {
+  const searchPaths = options.searchPaths?.length ? options.searchPaths : ["."];
+  const formats = options.formats?.length ? options.formats : [".json", ".rc"];
+  const matches: Array<{ path: string; values: Record<string, unknown> }> = [];
+
+  for (const searchPath of searchPaths) {
+    for (const format of formats) {
+      const path = resolve(join(searchPath, configFileName(options.name, format)));
+      const content = await readTextFile(path);
+      if (content === undefined) continue;
+      matches.push({ path, values: parseConfig(content, path, format, options.parser) });
+      break;
+    }
+    if (matches.length && !options.mergeConfigs) break;
+  }
+
+  if (!matches.length) return { values: {} };
+
+  // Earlier paths win, including when an explicitly undefined value is present.
+  const values: Record<string, unknown> = {};
+  for (const match of matches.slice().reverse()) Object.assign(values, match.values);
+  return { path: matches[0].path, values };
+}
+
+function configFileName(name: string, format: string): string {
+  return format === ".rc" ? `.${name}rc` : `${name}${format}`;
+}
+
+function parseConfig(
+  content: string,
+  path: string,
+  format: string,
+  parser?: ConfigOptions["parser"],
+): Record<string, unknown> {
+  try {
+    const parsed = parser ? parser(content) : format === ".rc" ? parseRc(content) : JSON.parse(content);
+    if (!isPlainObject(parsed)) throw new TypeError("Configuration must be a plain object.");
+    return flattenConfig(parsed);
+  } catch (error) {
+    throw new ConfigParseError(path, error);
+  }
+}
+
+function parseRc(content: string): Record<string, unknown> {
+  const result: Record<string, unknown> = {};
+  for (const rawLine of content.split(/\\r?\
/)) {
+    const line = rawLine.trim();
+    if (!line || line.startsWith("#")) continue;
+    const separator = line.indexOf("=");
+    if (separator === -1) throw new TypeError("Expected key=value.");
+    const key = line.slice(0, separator).trim();
+    let value = line.slice(separator + 1).trim();
+    if (!key) throw new TypeError("Missing configuration key.");
+    if (value.startsWith('"') && value.endsWith('"') && value.length >= 2) {
+      value = value.slice(1, -1);
+    }
+    result[key] = value === "true" ? true : value === "false" ? false :
+      value !== "" && /^[-+]?(?:\\d+\\.?\\d*|\\.\\d+)$/.test(value) ? Number(value) : value;
+  }
+  return result;
+}
+
+function flattenConfig(
+  value: Record<string, unknown>,
+  prefix = "",
+  result: Record<string, unknown> = {},
+): Record<string, unknown> {
+  for (const [rawKey, child] of Object.entries(value)) {
+    const key = rawKey.replace(/-([a-zA-Z0-9])/g, (_, letter) => letter.toUpperCase());
+    const name = prefix ? `${prefix}.${key}` : key;
+    if (isPlainObject(child)) flattenConfig(child, name, result);
+    else result[name] = child;
+  }
+  return result;
+}
+
+function isPlainObject(value: unknown): value is Record<string, unknown> {
+  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
+  const prototype = Object.getPrototypeOf(value);
+  return prototype === Object.prototype || prototype === null;
+}
+
+async function readTextFile(path: string): Promise<string | undefined> {
+  try {
+    // dnt-shim-ignore
+    if ((globalThis as any).Deno) return await (globalThis as any).Deno.readTextFile(path);
+    const fs = await import("node:fs/promises");
+    return await fs.readFile(path, "utf8");
+  } catch (error: any) {
+    if (error?.name === "NotFound" || error?.code === "ENOENT") return undefined;
+    throw error;
+  }
+}
