+
+async function configDir(files: Record<string, string>): Promise<string> {
+  const dir = await Deno.makeTempDir();
+  await Promise.all(Object.entries(files).map(([name, content]) =>
+    Deno.writeTextFile(join(dir, name), content)
+  ));
+  return dir;
+}
+
+test("command: json config values, nesting, and CLI precedence", async () => {
+  const dir = await configDir({
+    "app.json": JSON.stringify({
+      "max-count": 0,
+      enabled: false,
+      tags: ["one", "two"],
+      nested: { "child-value": "value" },
+      ignored: true,
+    }),
+  });
+  const cmd = new Command()
+    .throwErrors()
+    .config({ name: "app", searchPaths: [dir] })
+    .option("--max-count <count:number>", "...")
+    .option("--enabled", "...")
+    .option("--tags <tag:string>", "...", { collect: true })
+    .option("--nested.child-value <value>", "...");
+
+  const result = await cmd.parse(["--max-count", "2"]);
+  assertEquals(result.options, {
+    maxCount: 2,
+    enabled: false,
+    tags: ["one", "two"],
+    nested: { childValue: "value" },
+  });
+  assertEquals(cmd.getConfigValues(), {
+    maxCount: 0,
+    enabled: false,
+    tags: ["one", "two"],
+    "nested.childValue": "value",
+    ignored: true,
+  });
+  assertEquals(cmd.getConfigPath(), join(dir, "app.json"));
+});
+
+test("command: rc config and merged search paths", async () => {
+  const first = await configDir({ ".apprc": "port=3000\
enabled=false\
label=\\"two words\\"" });
+  const second = await configDir({ ".apprc": "port=4000\
label=second" });
+  const cmd = new Command()
+    .throwErrors()
+    .config({ name: "app", searchPaths: [first, second], mergeConfigs: true })
+    .option("--port <port:number>", "...")
+    .option("--enabled", "...")
+    .option("--label <label>", "...");
+  const result = await cmd.parse([]);
+  assertEquals(result.options, { port: 3000, enabled: false, label: "two words" });
+  assertEquals(cmd.getConfigPath(), join(first, ".apprc"));
